// Supadata transcript API (https://docs.supadata.ai). Runs from Supadata's
// infrastructure, so it does not depend on YouTube accepting Vercel's
// datacenter IPs. Only used when SUPADATA_API_KEY is configured.
// mode=native: only existing captions (manual or auto-generated), 1 credit per
// request; never AI generation, which is billed per minute.
import { NO_CAPTIONS_MESSAGE, TranscriptExtractionError, VIDEO_UNAVAILABLE_MESSAGE } from "./youtubeTranscriptService.js";

const API_BASE = "https://api.supadata.ai/v1";

export class SupadataError extends Error {
  constructor(message, { status = null, code = null, quota = false, config = false } = {}) {
    super(message);
    this.name = "SupadataError";
    this.status = status;
    this.code = code;
    this.quota = quota;
    this.config = config;
  }
}

async function fetchJson(url, apiKey, fetchImpl, timeoutMs) {
  const response = await fetchImpl(url, {
    headers: { "x-api-key": apiKey, Accept: "application/json" },
    signal: AbortSignal.timeout(timeoutMs),
  });
  const raw = await response.text();
  let body = null;
  try { body = raw ? JSON.parse(raw) : null; } catch { /* non-JSON error page */ }
  return { status: response.status, body };
}

export function subtitlesFromSupadata(content) {
  if (!Array.isArray(content)) return [];
  return content
    .map((chunk) => ({
      start: Number(chunk?.offset) / 1000,
      duration: Number(chunk?.duration) / 1000,
      text: String(chunk?.text || "").replace(/\s+/g, " ").trim(),
    }))
    .filter((item) => item.text && Number.isFinite(item.start) && item.start >= 0)
    .map((item) => ({ ...item, duration: Number.isFinite(item.duration) && item.duration > 0 ? item.duration : 2 }));
}

export async function fetchSupadataTranscript(id, env, { fetchImpl = fetch, wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms)), pollBudgetMs = 20_000 } = {}) {
  const apiKey = String(env.SUPADATA_API_KEY || "").trim();
  if (!apiKey) throw new SupadataError("Supadata is not configured", { config: true });
  const videoUrl = `https://www.youtube.com/watch?v=${id}`;
  const query = new URLSearchParams({ url: videoUrl, lang: "en", mode: "native" });
  let { status, body } = await fetchJson(`${API_BASE}/transcript?${query}`, apiKey, fetchImpl, 20_000);

  // Large videos may be processed asynchronously; poll the job briefly.
  if (status === 202 && body?.jobId) {
    const jobId = body.jobId;
    const deadline = Date.now() + pollBudgetMs;
    // Reliability first: 1.5s then exponential backoff (max 4s) to avoid Supadata 429.
    for (let poll = 0; ; poll += 1) {
      if (Date.now() >= deadline) throw new SupadataError("Supadata job timed out", { status: 202, code: "job-timeout" });
      await wait(Math.min(4000, 1500 * 1.5 ** poll));
      ({ status, body } = await fetchJson(`${API_BASE}/transcript/${encodeURIComponent(jobId)}`, apiKey, fetchImpl, 10_000));
      if (status !== 200) break;
      if (body?.status === "failed") throw new SupadataError("Supadata job failed", { status, code: "job-failed" });
      if (body?.result?.content) { body = body.result; break; }
      if (body?.content) break;
    }
  }

  if (status === 200 && body?.content) {
    const subtitles = subtitlesFromSupadata(body.content);
    if (!subtitles.length) throw new TranscriptExtractionError(NO_CAPTIONS_MESSAGE, { reason: "no_captions", statusCode: 404 });
    return {
      videoId: id,
      title: "",
      language: String(body.lang || "en"),
      originalLanguage: String(body.lang || "en"),
      translated: false,
      isAutoGenerated: null,
      availableLanguages: Array.isArray(body.availableLangs) ? body.availableLangs : [],
      subtitles,
      extractor: "supadata",
      diagnostics: [{ extractor: "supadata", step: "transcript", status, found: subtitles.length }],
      attempt: 1,
    };
  }

  const code = body?.error || null;
  // Definitive answers about the video itself: no point trying other paths.
  if (status === 206 || code === "transcript-unavailable") throw new TranscriptExtractionError(NO_CAPTIONS_MESSAGE, { reason: "no_captions", statusCode: 404 });
  if (status === 404 || code === "not-found") throw new TranscriptExtractionError(VIDEO_UNAVAILABLE_MESSAGE, { reason: "video_unavailable", statusCode: 404 });
  // Key / quota / service problems: fall back to the other extractors.
  if (status === 401 || status === 403) throw new SupadataError("Supadata API key rejected", { status, code, config: true });
  if (status === 402 || status === 429) throw new SupadataError("Supadata quota or rate limit reached", { status, code, quota: true });
  throw new SupadataError(`Supadata returned HTTP ${status}`, { status, code });
}
